html:
{# =========================================================
   PAYMENT REQUEST PRINT FORMAT
   - For ERPNext Payment Request
   - Supports Supplier / Customer / Employee / Others
   - Keeps fixed signatures:
       Prepared By  : Bahja Abdinasir Abdulkadir
       Reviewed By  : Hassan Mukhtar Yahye
       Approved By  : Dr. Abdifatah Ibrahim Omar
========================================================= #}

{% set currency = doc.currency or doc.transaction_currency or doc.company_currency or "USD" %}
{% set amount = doc.grand_total or doc.outstanding_amount or doc.payment_amount or doc.total_amount or 0 %}
{% set party_name = doc.party_name or doc.party or "-" %}
{% set reference_doctype = doc.reference_doctype or "-" %}
{% set reference_name = doc.reference_name or "-" %}
{% set request_type = doc.payment_request_type or "-" %}
{% set prepared_by_user = doc.owner %}
{% set prepared_by_name = frappe.db.get_value("User", prepared_by_user, "full_name") or prepared_by_user %}

<style>
  .pr-wrap{
    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    font-size: 12.5px;
    color: #1f2d3d;
    line-height: 1.45;
  }

  .pr-title{
    text-align: center;
    margin: 6px 0 10px 0;
  }

  .pr-title h2{
    margin: 0;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: .8px;
    text-transform: uppercase;
  }

  .pr-title .ref{
    margin-top: 4px;
    font-size: 11px;
    color: #6c757d;
  }

  .pr-divider{
    border: 0;
    border-top: 1px solid #222;
    margin: 10px 0 14px 0;
    opacity: .85;
  }

  .pr-grid{
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .pr-grid td{
    padding: 7px 8px;
    vertical-align: top;
  }

  .pr-k{
    width: 22%;
    font-weight: 800;
    color: #212529;
    white-space: nowrap;
  }

  .pr-v{
    width: 28%;
  }

  .pr-message-box{
    margin-top: 14px;
    border: 1px solid #dfe6e9;
    border-radius: 10px;
    padding: 14px 16px;
    background: #fbfcfd;
    min-height: 120px;
  }

  .pr-message-title{
    font-weight: 800;
    margin-bottom: 8px;
    color: #212529;
  }

  .pr-message-text{
    white-space: pre-wrap;
    line-height: 1.6;
  }

  .pr-amount-box{
    margin-top: 14px;
    border: 1px solid #dfe6e9;
    border-radius: 10px;
    padding: 14px 16px;
    background: #f8fafc;
  }

  .pr-amount-row{
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 16px;
  }

  .pr-amount-label{
    font-weight: 900;
    font-size: 13px;
    color: #212529;
  }

  .pr-amount-value{
    font-weight: 900;
    font-size: 20px;
    color: #111;
    font-variant-numeric: tabular-nums;
  }

  .pr-sign-row{
    margin-top: 55px;
    width: 100%;
    table-layout: fixed;
  }

  .pr-sign-row td{
    width: 33.33%;
    text-align: center;
    vertical-align: top;
    padding: 0 12px;
  }

  .pr-sign-line{
    border-top: 1.8px solid #2f343a;
    margin-top: 52px;
    padding-top: 6px;
    font-weight: 800;
    font-size: 12px;
    color: #212529;
  }

  .pr-sign-name{
    margin-top: 4px;
    font-size: 11.5px;
    font-weight: 700;
    color: #212529;
    min-height: 16px;
  }

  .pr-footer{
    margin-top: 24px;
    padding-top: 8px;
    border-top: 1px solid #e9ecef;
    text-align: center;
    font-size: 10.5px;
    color: #6c757d;
  }
</style>

<div class="pr-wrap">
  {{ letter_head }}

  <div class="pr-title">
    <h2>Payment Request</h2>
    <div class="ref">Request No: {{ doc.name }}</div>
  </div>

  <hr class="pr-divider">

  <table class="pr-grid">
    <tr>
      <td class="pr-k">Payment Request Type</td>
      <td class="pr-v">{{ request_type }}</td>

      <td class="pr-k">Currency</td>
      <td class="pr-v">{{ currency }}</td>
    </tr>

    <tr>
      <td class="pr-k">Party Type</td>
      <td class="pr-v">{{ doc.party_type or "-" }}</td>

      <td class="pr-k">Party</td>
      <td class="pr-v">{{ party_name }}</td>
    </tr>

    <tr>
      <td class="pr-k">Reference DocType</td>
      <td class="pr-v">{{ reference_doctype }}</td>

      <td class="pr-k">Reference Name</td>
      <td class="pr-v">{{ reference_name }}</td>
    </tr>

    <tr>
      <td class="pr-k">Posting Date</td>
      <td class="pr-v">{{ frappe.utils.formatdate(doc.creation, "dd-MM-yyyy") if doc.creation else "-" }}</td>

      <!--<td class="pr-k">Status</td>-->
      <!--<td class="pr-v">{{ doc.status or doc.workflow_state or doc.docstatus }}</td>-->
    </tr>
  </table>

  <div class="pr-amount-box">
    <div class="pr-amount-row">
      <div class="pr-amount-label">Requested Amount</div>
      <div class="pr-amount-value">{{ frappe.utils.fmt_money(amount, currency=currency) }}</div>
    </div>
  </div>

  <div class="pr-message-box">
    <div class="pr-message-title">Message</div>
    <div class="pr-message-text">
Hello,

Requesting payment against {{ reference_doctype }} {{ reference_name }} for amount {{ frappe.utils.fmt_money(amount, currency=currency) }}.

Please process this payment accordingly.

Thank you.
    </div>
  </div>

  <table class="pr-sign-row">
    <tr>
      <td>
        <div class="pr-sign-line">Prepared By</div>
        <div class="pr-sign-name">{{ prepared_by_name }}</div>
      </td>

      <td>
        <div class="pr-sign-line">Reviewed By</div>
        <div class="pr-sign-name">Hassan Mukhtar Yahye</div>
      </td>

      <td>
        <div class="pr-sign-line">Approved By</div>
        <div class="pr-sign-name">Dr. Abdifatah Ibrahim Omar</div>
      </td>
    </tr>
  </table>

  <div class="pr-footer">
    This document is system generated for internal payment approval and audit purposes.
  </div>
</div>
